-- Canonical configurable execution duration. Old active/historical selected values
-- cannot be reinterpreted as uncapped or assigned a different clock anchor.
LOCK TABLE occ.turn_journal_operations IN ACCESS EXCLUSIVE MODE;
DO $$ BEGIN
  IF EXISTS (SELECT 1 FROM occ.turn_journal_operations WHERE operation_kind IN
    ('execution-intent','execution-start','execution-interruption','deadline-control')) THEN
    RAISE EXCEPTION 'Unsupported selected execution records require explicit disposition' USING ERRCODE='23514';
  END IF;
END $$;

